-- The Termite Engineer R.C.C., Rifts Dimension Book 2: Phase World p.93-94.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-termite-engineer-class.sql
--
-- Generated by scripts/class-check.mjs --emit-script from a validated draft.
-- Apostrophes are doubled and non-ASCII is spliced with char(); CR is stripped.
-- Run class-check on THIS file before applying - the ASCII/CRLF pre-flight only
-- fires against the real artifact.


-- The class itself. INSERT ... WHERE NOT EXISTS rather than INSERT OR IGNORE,
-- so re-running the script is a no-op instead of a silent partial write.
INSERT INTO imported_classes (class_id, name, system, markdown, status, created_by)
SELECT 'termite-engineer', 'Termite Engineer', 'rifts', '---
id: termite-engineer
name: Termite Engineer
system: rifts
category: rcc
source_book: Rifts Dimension Book 2: Phase World p.93-94
attribute_dice:
  IQ: "3d6+6"
  ME: "3d6"
  MA: "3d6"
  PS: "3d6"
  PP: "3d6+6"
  PE: "4d6+3"
  PB: "2d6"
  Spd: "4d6"
mdc_base: "1d6x10 plus 3d6 per level"
ppe_base: "3d6"
bonuses:
  combat: { attacks_base: 2, strike: 1, parry: 2, dodge: 2, roll: 3, pull_punch: 3 }
  saves: { spell_magic: 1, horror_factor: 6 }
  at_level:
    - { level: 4, combat: { attacks: 1 } }
    - { level: 5, combat: { parry: 1, dodge: 1 } }
    - { level: 6, combat: { strike: 1 } }
    - { level: 8, combat: { attacks: 1, parry: 1, dodge: 1 } }
    - { level: 10, combat: { strike: 1 } }
    - { level: 12, combat: { attacks: 1, parry: 1, dodge: 1 } }
psionics:
  isp_base: "3d6x10 plus 10 per level of experience"
  powers: ["See Aura", "See The Invisible", "Sense Magic", "Mind Block Auto-Defense", "Telekinesis (Super)", "Telepathy"]
natural_abilities:
  - { name: "Secrete Chitin", description: "The ability the whole race is built around. The engineer secretes a gooey substance and moulds it into mega-damage structures: up to 10 M.D.C. per level of experience in a melee round, costing one attack or action. Fired at a target it engulfs and entangles - +3 to strike, range 60 feet (18.3 m) - and the target stays trapped until it has destroyed that much M.D.C. The same chitin plugs holes in walls and in starship hulls, and makes manacles for prisoners. It CANNOT repair body armour." }
  - { name: "Chitin Molding", description: "The skill that goes with the secretion, and the book states it as a percentage rather than putting it in a catalog: 50% plus 2% per level of experience for an ordinary engineer, and +10% on top of that - so 60% plus 2% per level - for a sentient one. Every hive termite has it, skills or no skills." }
  - { name: "Multi-Spectrum Vision", description: "Sight equal to a cybernetic multi-optics eye, and radar, out to 2000 feet (610 m)." }
  - { name: "Regeneration", description: "Regrows lost limbs and heals 1d4x10 M.D.C. per eight hour rest period." }
  - { name: "Hive Recognition", description: "Psionically recognises members of its own hive." }
  - { name: "Free-Will Telepathy", description: "Telepathy costs the engineer no I.S.P. at all, and works only between members of its hive." }
  - { name: "Four Arms", description: "Bipedal, with two sets of arms ending in tiny fingers - which is what makes an engineer a sculptor rather than a labourer. Claws add 1d6 M.D. to hand to hand damage." }
  - { name: "Horror Factor", description: "10. A number the engineer projects, which the sheet has no field for." }
  - { name: "Size and Weight", description: "7 feet (2.1 m) tall and 300 lbs (136 kg)." }
  - { name: "Average Life Span", description: "200 years." }
side_effects: "DOUBLE DAMAGE FROM PSIONIC ATTACKS. Every hive-spawn takes it, and there is no field on the sheet that doubles incoming damage by type, so this is prose the G.M. applies. The other standing cost is social: an engineer faces the same prejudice every hive-spawn does, and free ones end up among criminals, outcasts and adventurers."
skills:
  occ_skills:
    - { choose: 2, from: ["Language: Other"], bonus: 20, note: "Two Languages of Choice (+20%). The catalog''s repeatable Language: Other row is what an any-language pick resolves through." }
    - { name: "Mathematics: Basic", bonus: 15, note: "Printed as Basic Math (+15%)." }
    - { name: "Carpentry", bonus: 10, note: "+10% bonus over base. The catalog files Carpentry under Wilderness; it is granted here outright, so no category listing is needed for it." }
    - { name: "Basic Electronics", bonus: 10, note: "+10% bonus over base." }
    - { choose: 1, categories: ["Weapon Proficiencies"], note: "One W.P. of Choice." }
  occ_related_skills:
    count: 12
    categories:
      - { name: "Communications", bonus: 5 }
      - "Domestic"
      - { name: "Electrical", bonus: 5 }
      - { name: "Mechanical", bonus: 5 }
      - "Medical"
      - { name: "Physical", only: ["Swimming", "Climbing"] }
      - { name: "Pilot", bonus: 5 }
      - { name: "Pilot Related", bonus: 5 }
      - { name: "Rogue", only: ["Prowl"], bonus: 5 }
      - { name: "Science", bonus: 10 }
      - { name: "Technical", bonus: 5 }
      - "Weapon Proficiencies"
      - "Wilderness"
    schedule: [{ level: 4, count: 2 }, { level: 7, count: 1 }, { level: 10, count: 1 }, { level: 12, count: 1 }]
    note: "Twelve at creation, two more at level four and one more at levels seven, ten and twelve. W.P. is printed Any EXCEPT hand to hand skills, and that exclusion is already enforced from the other side - all five hand to hand skills are Physical skills, and Physical here is Swimming and Climbing only. Espionage and Military are printed None and are omitted rather than listed."
  secondary_skills:
    count: 5
    note: "Five secondary skills from the same list, at the base skill level and without the bonuses in parentheses."
extraction_notes: |
  - Read from the OCR cache of a scan and verified against 200 dpi renders of
    printed 93 and 94. The entry starts halfway down the left column of printed
    93, under the Vacuum Wasps'' Secondary Skills line, and ends on printed 94 at
    Secondary Skills. Both pages were read in full because this chapter
    INTERLEAVES playable entries with NPC ones: the right column of printed 94
    is the Worker Ants, an entry the book marks NPC Villains, and its stat block
    sits beside the engineer''s skill list on the same page.
  - NOTHING ON PRINTED 88-95 CARRIES A `Money:` OR A `Standard Equipment:` LINE.
    Grepped across the whole Star Hives chapter rather than inferred from the
    two pages this class needs. Both come from the O.C.C. if one is taken.
  - THE SENTIENT I.Q. IS THE ONE STORED. The book prints "I.Q. 3D6 (3D6+6)" and
    says the parenthetical is for sentient termites. A player character IS the
    sentient kind: the skill line reads that normal engineers have only the
    Chitin Molding skill and that the list below it belongs to sentient ones, so
    importing 3d6 alongside that list would be describing two different
    creatures. 3d6+6 is stored and the hive-controlled 3d6 is recorded here.
  - CHITIN MOLDING IS NOT MADE A CATALOG SKILL. The book states it as a bare
    percentage inside the R.C.C. Skills line and defines it nowhere else; it
    belongs to this one race, and a skills row would offer it to every class
    granting whichever category it was filed under. Stored as a natural ability
    carrying both numbers - 50% +2% per level, and +10% for a sentient engineer
    - which is the same treatment the Phantom''s Limited Mind-Reading already
    gets in this book. Contrast the Pleasurer in this same batch, whose printed
    percentage IS a catalog skill (Disguise) and is granted as one.
  - `psionics.type` IS NOT SET, BECAUSE THE BOOK DOES NOT SET IT. The entry
    lists six powers and an I.S.P. pool and never says minor, major or master.
    An invented tier would change the psionic save target and would read as the
    book''s. Same call as the Vacuum Wasp in this batch, and the opposite of the
    Pleasurer, which the book calls a major psionic outright.
  - THE BONUS LINE DOES NOT DOUBLE-COUNT. It closes "All these are in addition
    to attribute bonuses", so derive.js adding its own P.P. figure on top is
    right rather than a second helping. Read the heading, not the numbers.
  - `attacks_base: 2` IS STATED RATHER THAN INHERITED. The book gives two hand
    to hand attacks at level one, which happens to equal the app''s default, and
    it is written out because the engineer can never buy a hand to hand skill to
    change it - W.P. is Any except hand to hand, and Physical is Swimming and
    Climbing only. The later attacks and the strike, parry and dodge
    progressions are in `bonuses.at_level`. This entry states no initiative
    bonus at all, which is transcribed rather than filled in.
  - ROGUE: PROWL ONLY IS A CROSS-CATEGORY GRANT AND ITS +5% DOES NOT LAND. The
    catalog files Prowl under Physical, and `categoryAllows` admits a
    cross-category `only` because the class also lists Physical, so the skill is
    reachable. `categoryBonus` deliberately keys on the skill''s REAL category,
    so the +5% printed beside Rogue is not applied to it. Same as the Vacuum
    Wasp in this batch.
  - A CATEGORY PRINTED `None` IS AN EXCLUSION. Espionage and Military are
    printed None and are omitted from `categories` entirely.
  - A RACE CARRIES NO xp_table. Printed 183 heads the column "Pleasurer &
    Termite Engineers"; composition is race-primary, so a table here would win
    over the occupation''s and silently drop it. The ladder is: 0, 2,151, 4,301,
    8,601, 17,201, 25,501, 36,001, 52,001, 73,001, 98,001, 134,001, 184,001,
    240,001, 295,001, 365,001. Read off a 250 dpi render of printed 183; every
    band''s low is the previous band''s high plus one, which is fifteen readings
    checking each other. It is the same ladder the Pleasurer in this batch
    records.
  - A natural M.D.C. creature, so there is no S.D.C., no hit points and no
    CORE_SDC_BY_CLASS entry.
  - Related and secondary skills come from the O.C.C. in the general case, but
    this race prints its own lists of both, so both are stored.
---

## Lore

Termite engineers build the Star Hives. They are seven feet of bipedal insect
with two pairs of arms and small precise fingers, and they secrete a mega-damage
glue they mould into whatever the hive needs - walls, chambers, repairs to a
hull. They are the cleverest thing in a hive by a long way, and the likeliest to
wake up.

## The ones who woke up

A termite engineer that becomes self-aware can learn an enormous amount of
science and technology, which is what makes this an Optional Player Character
rather than a monster entry. Printed 183 gives it a share of a real experience
ladder, alongside the Pleasurer.

It gets no warmer a welcome than any other hive-spawn. Most fleets in the Three
Galaxies destroy a Star Hive on sight, so a free engineer generally ends up
keeping company with criminals, outcasts and adventurers.

Available as a player character with the Game Master''s approval. Alignment: any
when sentient; aberrant or diabolic while under the control of a hive.

## GM Notes

The chitin is the interesting half of this class, and almost none of it is
combat. Ten M.D.C. per level per melee round, mouldable, is a party that can seal
a breached hull, build a wall across a corridor, or manacle a prisoner nothing
else will hold - and the same secretion fired at a target entangles it until it
chews through that much M.D.C. It cannot patch body armour, which is the one
thing every player will ask for first.
', 'published', 'data-script'
WHERE NOT EXISTS (SELECT 1 FROM imported_classes WHERE class_id = 'termite-engineer');


-- Read the result back rather than trusting the exit code. d1-apply prints
-- these, and a CR in the stored markdown means the checkout mangled the file.
SELECT class_id, name, status, length(markdown) AS bytes, instr(markdown, char(13)) > 0 AS has_cr
  FROM imported_classes WHERE class_id = 'termite-engineer';

